import { readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";

// MB-16: PNG icons generated by scripts/build-icons.mjs, favicon from the brand symbol.
// No @types/node (SPEC 4.1): read the PNG as latin1 so each char is one byte; width and height sit at 16 and 20.
const u32 = (bytes: string, at: number) =>
  [0, 1, 2, 3].reduce((n, i) => n * 256 + bytes.charCodeAt(at + i), 0);
const size = (path: string) => {
  const png = readFileSync(path, "latin1");
  return [u32(png, 16), u32(png, 20)];
};

describe("MB-16 app icons", () => {
  test.each([
    ["public/brand/icon-192.png", 192],
    ["public/brand/icon-512.png", 512],
    ["public/brand/icon-maskable-512.png", 512],
  ])("%s is %i px square", (path, px) => {
    expect(size(path)).toEqual([px, px]);
  });

  test("favicon is the brand symbol and the shell links it", () => {
    expect(readFileSync("public/brand/favicon.svg", "utf8")).toContain("<title>Dove bevo</title>");
    expect(readFileSync("index.html", "utf8")).toContain('href="/brand/favicon.svg"');
  });
});
